export interface User {
  id: string;
  active: boolean;
}

export interface Report {
  ready: boolean;
  ownerId: string;
  sharedWith: string[];
}

export const mayDownload = (report: Report, user: User): boolean =>
  user.active &&
  report.ready &&
  (report.ownerId === user.id || report.sharedWith.includes(user.id));

